 "RulesSource": {
  "RulesString": "drop tcp 10.30.1.0/24 any -> 10.30.3.0/24 any (msg:\"shop-db-in-shop-db\"; flow:to_server; sid:1; rev:1;)\ndrop tcp $shop_db_in_shop_db_2_SRC any -> 10.30.3.0/24 0:1023 (msg:\"shop-db-in-shop-db-2\"; flow:to_server; sid:2; rev:1;)\ndrop ip $shop_db_in_shop_db_2_SRC any -> 10.30.3.0/24 any (msg:\"shop-db-in-shop-db-2\"; flow:to_server; ip_proto:!6; sid:3; rev:1;)\ndrop tcp [10.30.0.0/24,10.30.2.0/24,10.30.4.0/22,10.30.8.0/21,10.30.16.0/20,10.30.32.0/19,10.30.64.0/18,10.30.128.0/17] any -> 10.30.3.0/24 0:1023 (msg:\"shop-db-in-shop-db-3\"; flow:to_server; sid:4; rev:1;)\ndrop ip [10.30.0.0/24,10.30.2.0/24,10.30.4.0/22,10.30.8.0/21,10.30.16.0/20,10.30.32.0/19,10.30.64.0/18,10.30.128.0/17] any -> 10.30.3.0/24 any (msg:\"shop-db-in-shop-db-3\"; flow:to_server; ip_proto:!1; ip_proto:!6; sid:5; rev:1;)\ndrop ip 10.30.1.0/24 any -> 10.30.3.0/24 any (msg:\"shop-db-in-shop-db-4\"; flow:to_server; ip_proto:!1; ip_proto:!6; sid:6; rev:1;)\npass tcp 10.30.2.20/31 any -> 10.30.3.30/32 5432 (msg:\"shop-app-to-shop-db\"; flow:to_server; sid:7; rev:1;)\ndrop ip $shop_app_members any -> $shop any (msg:\"shop-app-outbound-rest\"; flow:to_server; sid:8; rev:1;)\ndrop ip $shop_db_members any -> $shop any (msg:\"shop-db-outbound-rest\"; flow:to_server; sid:9; rev:1;)\npass tcp 10.30.1.10/32 any -> 10.30.2.20/31 8080 (msg:\"shop-web-to-shop-app\"; flow:to_server; sid:10; rev:1;)\ndrop ip $shop_web_members any -> $shop any (msg:\"shop-web-outbound-rest\"; flow:to_server; sid:11; rev:1;)\npass tcp 0.0.0.0/0 any -> $shop_web 443 (msg:\"shop-web-in-1\"; flow:to_server; sid:12; rev:1;)\npass tcp ::/0 any -> $shop_web 443 (msg:\"shop-web-in-2\"; flow:to_server; sid:13; rev:1;)\npass tcp 0.0.0.0/0 any -> $shop_web 80 (msg:\"shop-web-in-3\"; flow:to_server; sid:14; rev:1;)\npass tcp $shop_bastion any -> $shop_web 22 (msg:\"shop-web-in-4\"; flow:to_server; sid:15; rev:1;)\npass icmp 10.0.0.0/8 any -> $shop_web any (msg:\"shop-web-in-5\"; flow:to_server; ip_proto:1; itype:3; icode